// Message names, as the spec gives them.
const (
	// Ping server to determine whether connection is alive
	// Payload: Ping.
	MessagePing = "ping"
	// Pong is a response to ping message
	// Payload: Pong.
	MessagePong = "pong"
	// Server heartbeat sent if no subscription traffic within 1 second (approximately)
	// Payload: Heartbeat.
	MessageHeartbeat = "heartbeat"
	// Status sent on connection or system status changes.
	// Payload: SystemStatus.
	MessageSystemStatus = "systemStatus"
	// Subscription status response to subscribe, unsubscribe or exchange initiated unsubscribe.
	// Payload: SubscriptionStatus.
	MessageSubscriptionStatus = "subscriptionStatus"
	// Dummy message with no real life details
	// Payload: DummyCurrencyInfoPayload.
	MessageDummyCurrencyInfo = "dummyCurrencyInfo"
	// Subscribe to a topic on a single or multiple currency pairs.
	// Payload: Subscribe.
	MessageSubscribe = "subscribe"
	// Unsubscribe, can specify a channelID or multiple currency pairs.
	// Payload: Unsubscribe.
	MessageUnsubscribe = "unsubscribe"
)

// MessagePingCorrelationIDLocation is where a ping message carries its
// correlation ID, as an AsyncAPI runtime expression.
const MessagePingCorrelationIDLocation = "$message.payload#/reqid"

// MessagePongCorrelationIDLocation is where a pong message carries its
// correlation ID, as an AsyncAPI runtime expression.
const MessagePongCorrelationIDLocation = "$message.payload#/reqid"

// MessageDummyCurrencyInfoCorrelationIDLocation is where a dummyCurrencyInfo message carries its
// correlation ID, as an AsyncAPI runtime expression.
const MessageDummyCurrencyInfoCorrelationIDLocation = "$message.payload#/reqid"

// MessageSubscribeCorrelationIDLocation is where a subscribe message carries its
// correlation ID, as an AsyncAPI runtime expression.
const MessageSubscribeCorrelationIDLocation = "$message.payload#/reqid"

// MessageUnsubscribeCorrelationIDLocation is where a unsubscribe message carries its
// correlation ID, as an AsyncAPI runtime expression.
const MessageUnsubscribeCorrelationIDLocation = "$message.payload#/reqid"

// ReceivedMessage is a decoded incoming message. Payload holds the payload
// type of the message Name names.
type ReceivedMessage struct {
	Name    string
	Payload any
}

var receivedMessages = []asyncapirt.Candidate{
	{
		Name: MessagePing,
		Matchers: []asyncapirt.Matcher{
			{Pointer: "/event", Value: "\"ping\""},
		},
		Decode: func(data []byte) (any, error) {
			var payload Ping
			if err := asyncapirt.UnmarshalStrict(data, &payload); err != nil {
				return nil, err
			}

			return payload, nil
		},
	},
	{
		Name: MessageSubscribe,
		Matchers: []asyncapirt.Matcher{
			{Pointer: "/event", Value: "\"subscribe\""},
		},
		Decode: func(data []byte) (any, error) {
			var payload Subscribe
			if err := asyncapirt.UnmarshalStrict(data, &payload); err != nil {
				return nil, err
			}

			return payload, nil
		},
	},
	{
		Name: MessageUnsubscribe,
		Matchers: []asyncapirt.Matcher{
			{Pointer: "/event", Value: "\"unsubscribe\""},
		},
		Decode: func(data []byte) (any, error) {
			var payload Unsubscribe
			if err := asyncapirt.UnmarshalStrict(data, &payload); err != nil {
				return nil, err
			}

			return payload, nil
		},
	},
}

// DecodeReceivedMessage works out which incoming message data is and decodes
// it. It fails with asyncapirt.ErrUnknownMessage when nothing matches and
// asyncapirt.ErrAmbiguousMessage when several messages match.
func DecodeReceivedMessage(data []byte) (ReceivedMessage, error) {
	name, payload, err := asyncapirt.DecodeMessage(data, receivedMessages)
	if err != nil {
		return ReceivedMessage{}, ctxerrors.Wrap(err, "decode received message")
	}

	return ReceivedMessage{Name: name, Payload: payload}, nil
}

// Handler receives incoming messages. Embed UnimplementedHandler to implement
// only the methods you need.
type Handler interface {
	// Ping server to determine whether connection is alive
	// Payload: Ping.
	HandlePing(ctx context.Context, payload Ping) error
	// Subscribe to a topic on a single or multiple currency pairs.
	// Payload: Subscribe.
	HandleSubscribe(ctx context.Context, payload Subscribe) error
	// Unsubscribe, can specify a channelID or multiple currency pairs.
	// Payload: Unsubscribe.
	HandleUnsubscribe(ctx context.Context, payload Unsubscribe) error
	// HandleUnknownMessage gets every message that matched nothing, with the
	// reason. Returning an error stops Client.Run.
	HandleUnknownMessage(ctx context.Context, data []byte, err error) error
}

// UnimplementedHandler ignores every message. Its HandleUnknownMessage logs a
// warning and keeps the receive loop running.
type UnimplementedHandler struct{}

// HandlePing ignores the message.
func (UnimplementedHandler) HandlePing(context.Context, Ping) error {
	return nil
}

// HandleSubscribe ignores the message.
func (UnimplementedHandler) HandleSubscribe(context.Context, Subscribe) error {
	return nil
}

// HandleUnsubscribe ignores the message.
func (UnimplementedHandler) HandleUnsubscribe(context.Context, Unsubscribe) error {
	return nil
}

// HandleUnknownMessage logs the message size and the reason, then continues.
func (UnimplementedHandler) HandleUnknownMessage(ctx context.Context, data []byte, err error) error {
	ctxscope.GetLogger(ctx).Warn(
		"ignoring incoming message",
		"err", err,
		"size_bytes", len(data),
		"reason", "no_matching_message",
	)

	return nil
}

// Dispatch passes message to the handler method for its name.
func Dispatch(ctx context.Context, handler Handler, message ReceivedMessage) error {
	switch message.Name {
	case MessagePing:
		payload, ok := message.Payload.(Ping)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandlePing(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessageSubscribe:
		payload, ok := message.Payload.(Subscribe)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleSubscribe(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessageUnsubscribe:
		payload, ok := message.Payload.(Unsubscribe)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleUnsubscribe(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	}

	return ctxerrors.Wrapf(asyncapirt.ErrUnknownMessage, "%s", message.Name)
}

// Client sends and receives this API's messages over a transport.
type Client struct {
	transport asyncapirt.Transport
}

// NewClient returns a client that uses transport.
func NewClient(transport asyncapirt.Transport) *Client {
	return &Client{transport: transport}
}

// Close closes the transport.
func (c *Client) Close() error {
	if err := c.transport.Close(); err != nil {
		return ctxerrors.Wrap(err, "close transport")
	}

	return nil
}

// Heartbeat validates payload and sends it as a MessageHeartbeat message.
func (c *Client) Heartbeat(ctx context.Context, payload Heartbeat) error {
	if err := asyncapirt.Send(ctx, c.transport, payload); err != nil {
		return ctxerrors.Wrapf(err, "send %s", MessageHeartbeat)
	}

	return nil
}

// SystemStatus validates payload and sends it as a MessageSystemStatus message.
func (c *Client) SystemStatus(ctx context.Context, payload SystemStatus) error {
	if err := asyncapirt.Send(ctx, c.transport, payload); err != nil {
		return ctxerrors.Wrapf(err, "send %s", MessageSystemStatus)
	}

	return nil
}

// Run reads messages until ctx ends or the transport fails and passes each one
// to handler. Messages that match nothing go to HandleUnknownMessage. Run stops
// at the first error a handler returns.
func (c *Client) Run(ctx context.Context, handler Handler) error {
	logger := ctxscope.GetLogger(ctx)
	logger.Info("receive loop started")

	for {
		data, err := c.transport.ReadMessage(ctx)
		if err != nil {
			if ctx.Err() != nil {
				logger.Info("receive loop stopped", "reason", "context_done")

				return ctxerrors.Wrap(ctx.Err(), "receive loop")
			}

			return ctxerrors.Wrap(err, "read message")
		}

		message, err := DecodeReceivedMessage(data)
		if err != nil {
			if handleErr := handler.HandleUnknownMessage(ctx, data, err); handleErr != nil {
				return ctxerrors.Wrap(handleErr, "handle unknown message")
			}

			continue
		}

		if err := Dispatch(ctx, handler, message); err != nil {
			return ctxerrors.Wrap(err, "dispatch message")
		}
	}
}
